sed -n '1,78p' src/mcp-apps/_shared/host.test.tsx > "$tmp"
cat >> "$tmp" <<'EOF'

describe("review repros", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
		bridge.callServerTool.mockResolvedValue({ isError: false });
	});
	afterEach(() => {
		restoreWindowProperty("parent", originalParentDescriptor);
		restoreWindowProperty("openai", originalOpenAiDescriptor);
	});

	it("repro: preserves a cached app result rather than restoring the originating card", async () => {
		Object.defineProperty(window, "openai", {
			configurable: true,
			value: {
				widgetState: {
					privateContent: {
						lobuViewSnapshot: {
							version: 1,
							data: { title: "Approved result" },
							resultIdentity: "approved-result-token",
						},
					},
				},
			},
		});
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://portable-host.example" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.hostContext = {
			toolInfo: { id: "originating-card", tool: { name: "render_lobu_view" } },
		};
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) => {
			if (name !== "restore_lobu_app_result") return { isError: false };
			return {
				isError: false,
				structuredContent:
					args.snapshot_capability === "approved-result-token"
						? {
								found: true,
								tool_name: "resolve_lobu_approval",
								data: { title: "Approved result" },
								view_state: {},
							}
						: {
								found: true,
								tool_name: "render_lobu_view",
								data: { title: "Pending approval" },
								view_state: {},
							},
			};
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data } = useMcpApp<{ title: string }>();
			return <span>{data?.title}</span>;
		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		expect(await screen.findByText("Approved result")).toBeInTheDocument();
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		await act(() => new Promise((resolve) => window.setTimeout(resolve, 0)));
		expect(screen.getByText("Approved result")).toBeInTheDocument();
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: {
				tool_call_id: "originating-card",
				tool_name: "render_lobu_view",
				snapshot_capability: "approved-result-token",
			},
		});
	});

	it("repro: correlates metadata that arrives before its matching widget cache", async () => {
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: window.location.origin },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		bridge.callServerTool.mockImplementation(async ({ name, arguments: args }) =>
			name === "restore_lobu_app_result" &&
			args.snapshot_capability === "late-widget-token"
				? {
						isError: false,
						structuredContent: {
							found: true,
							tool_name: "query_sdk",
							data: { title: "Server result" },
							view_state: { open: true },
						},
					}
				: { isError: false },
		);
		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return <span>{data?.title ?? "No result"}:{String(viewState.open)}</span>;
		}
		render(<Provider devMock={{ title: "dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => {
			window.dispatchEvent(new CustomEvent("openai:set_globals", {
				detail: { globals: {
					toolResponseMetadata: {
						mcp_tool_result: { _meta: {
							"lobu/mcp-app-snapshot-capability": "late-widget-token",
						} },
					},
				} },
			}));
			window.dispatchEvent(new CustomEvent("openai:set_globals", {
				detail: { globals: {
					widgetState: { privateContent: { lobuViewSnapshot: {
						version: 1,
						data: { title: "Cached result" },
						resultIdentity: "late-widget-token",
					} } },
				} },
			}));
		});
		expect(await screen.findByText("Cached result:undefined")).toBeInTheDocument();
		await act(() => new Promise((resolve) => window.setTimeout(resolve, 0)));
		expect(screen.getByText("Server result:true")).toBeInTheDocument();
	});
});
